loadstring("--!strict\n-- Config.luau | liv4cheets - Internal | Documents/robloxrivalsluau/\n-- Tabs: Combat | Visual | Exploits | Configs | Misc\n\nlocal Config = {}\n\nConfig.Defaults = {\n	Combat = {\n		AimbotEnabled = false,\n		AimFOV = 120,\n		AimSmoothing = 0.12,\n		AimPart = \"Head\",\n		TargetDummies = true,\n		Prediction = 0.015,\n		WallCheck = false,\n		SilentEnabled = false,\n		SilentFOV = 90,\n		SilentChance = 100,\n		TriggerEnabled = false,\n		TriggerKey = Enum.KeyCode.T,\n		TriggerDelay = 40,\n		RageEnabled = false, -- HIGH RISK, in Combat per spec\n		RageVoidSpam = false,\n		RageWeapon = \"Assault Rifle\",\n		RageAntiAim = false,\n	},\n	Visual = {\n		ESPEnabled = false,\n		Box = true,\n		FilledBox = false,\n		FilledNoOutline = false,\n		Skeleton = false,\n		Chams = false,\n		ChamsColor = Color3.fromRGB(198, 255, 62),\n		Name = true,\n		Distance = true,\n		HealthBar = true,\n		HealthBarThickness = 4,\n		Weapon = false,\n		ShowTeam = false,\n		MaxDistance = 2000,\n		TextSize = 13,\n	},\n	Exploits = {\n		Fly = false,\n		FlySpeed = 60,\n		Noclip = false,\n		AvatarUserId = \"\",\n		LevelValue = \"\",\n		StreakValue = \"\",\n		BoardValue = \"\",\n		RankedValue = \"\",\n		AnimAssetId = \"\",\n	},\n	SkinChanger = {\n		Weapon = \"\",\n		Skin = \"\",\n		ColorHex = \"C6FF3E\",\n		WrapHex = \"C6FF3E\",\n		Charm = \"None\",\n		Finisher = \"None\",\n	},\n	Misc = {\n		Theme = \"Default\", -- \"Default\" | \"Onyx\"\n		MenuFont = \"GothamMedium\", -- Robox font name\n		GameFontSize = 13,\n		Anims = true, -- hover / tween animations\n		Watermark = \"liv4cheets\",\n		ToggleKey = Enum.KeyCode.RightShift,\n		UnloadKey = Enum.KeyCode.End,\n	},\n	Meta = {\n		AllowedPlaceIds = { 17625359962, 17720162456 },\n		Name = \"liv4cheets - Internal\",\n		Version = \"v1.0-internal\",\n	},\n}\n\nlocal function deepCopy(t)\n	local out = {}\n	for k, v in pairs(t) do\n		if type(v) == \"table\" then\n			out[k] = deepCopy(v)\n		else\n			out[k] = v\n		end\n	end\n	return out\nend\n\nlocal function deepMerge(dst, src)\n	for k, v in pairs(src) do\n		if type(v) == \"table\" and type(dst[k]) == \"table\" then\n			deepMerge(dst[k], v)\n		else\n			dst[k] = v\n		end\n	end\n	return dst\nend\n\n-- migrate legacy RivalsConfig shape (Aimbot/ESP/...) if present\nlocal function migrate(t)\n	if t.Aimbot then\n		t.Combat = t.Combat or {}\n		t.Combat.AimbotEnabled = t.Aimbot.Enabled\n		t.Combat.AimFOV = t.Aimbot.FOV\n		t.Aimbot = nil\n	end\n	if t.ESP then\n		t.Visual = t.Visual or {}\n		t.Visual.ESPEnabled = t.ESP.Enabled\n		t.ESP = nil\n	end\n	return t\nend\n\nif getgenv().LIV4Config == nil and getgenv().RivalsConfig ~= nil then\n	getgenv().LIV4Config = migrate(getgenv().RivalsConfig)\nend\nif getgenv().LIV4Config == nil then\n	getgenv().LIV4Config = deepCopy(Config.Defaults)\nelse\n	local user = getgenv().LIV4Config\n	local merged = deepCopy(Config.Defaults)\n	deepMerge(merged, user)\n	getgenv().LIV4Config = merged\nend\ngetgenv().RivalsConfig = getgenv().LIV4Config -- alias for ported modules\n\nConfig.Current = getgenv().LIV4Config\n\nreturn Config\n\n--!strict\n-- Utils.luau | shared helpers (cloneref-safe, high UNC ok, no UNC required to load)\n\nlocal Utils = {}\n\n-- cloneref if available (Potassium/Wave), else passthrough\nlocal function cref<T>(inst: T): T\n	local f = (getgenv() :: any).cloneref or (rawget(_G, \"cloneref\") :: any)\n	if type(f) == \"function\" then\n		local ok, out = pcall(f, inst)\n		if ok and out then\n			return out\n		end\n	end\n	return inst\nend\n\nUtils.cloneref = cref\n\nUtils.Services = {\n	Players = cref(game:GetService(\"Players\")),\n	RunService = cref(game:GetService(\"RunService\")),\n	UserInputService = cref(game:GetService(\"UserInputService\")),\n	Workspace = cref(game:GetService(\"Workspace\")),\n	TweenService = cref(game:GetService(\"TweenService\")),\n	ReplicatedStorage = cref(game:GetService(\"ReplicatedStorage\")),\n}\n\nfunction Utils.LocalPlayer()\n	return Utils.Services.Players.LocalPlayer\nend\n\nfunction Utils.Character(plr)\n	plr = plr or Utils.LocalPlayer()\n	return plr and plr.Character or nil\nend\n\nfunction Utils.Humanoid(char): Humanoid?\n	if not char then\n		return nil\n	end\n	return char:FindFirstChildOfClass(\"Humanoid\")\nend\n\nfunction Utils.RootPart(char): BasePart?\n	if not char then\n		return nil\n	end\n	return char:FindFirstChild(\"HumanoidRootPart\")\nend\n\nfunction Utils.IsAlive(char): boolean\n	local hum = Utils.Humanoid(char)\n	return hum ~= nil and hum.Health > 0\nend\n\nfunction Utils.IsAlly(char): boolean\n	local flag = char and char:FindFirstChild(\"_is_ally\")\n	return flag ~= nil and (flag :: any).Value == true\nend\n\nfunction Utils.IsEnemy(player): boolean\n	local lp = Utils.LocalPlayer()\n	if player == lp then\n		return false\n	end\n	local cfg = (getgenv() :: any).RivalsConfig\n	-- team check for team modes\n	if cfg and cfg.Aimbot and cfg.Aimbot.TeamCheck then\n		if lp and lp.Team and player.Team and lp.Team == player.Team then\n			return false\n		end\n	end\n	local char = player.Character\n	if not char then\n		return false\n	end\n	if Utils.IsAlly(char) then\n		return false\n	end\n	return Utils.IsAlive(char)\nend\n\nfunction Utils.GetHitPart(char, mode: string?): BasePart?\n	if not char then\n		return nil\n	end\n	mode = mode or \"Head\"\n	if mode == \"Closest\" then\n		local cam = Utils.Services.Workspace.CurrentCamera\n		if not cam then\n			return nil\n		end\n		local best, bestD = nil, math.huge\n		for _, d in ipairs(char:GetChildren()) do\n			if d:IsA(\"BasePart\") then\n				local m = (d.Position - cam.CFrame.Position).Magnitude\n				if m < bestD then\n					bestD = m\n					best = d\n				end\n			end\n		end\n		return best\n	end\n	-- Rivals uses HitboxHead/HitboxBody alongside Head\n	return char:FindFirstChild(\"HitboxHead\")\n		or char:FindFirstChild(mode)\n		or char:FindFirstChild(\"Head\")\n		or char:FindFirstChild(\"HumanoidRootPart\")\nend\n\nfunction Utils.IsVisible(from: Vector3, target: BasePart, ignoreChar: Model?): boolean\n	local ws = Utils.Services.Workspace\n	local params = RaycastParams.new()\n	params.FilterType = Enum.RaycastFilterType.Exclude\n	local f = { ignoreChar, Utils.Character() }\n	params.FilterDescendantsInstances = f\n	local dir = target.Position - from\n	local res = ws:Raycast(from, dir, params)\n	if not res then\n		return true\n	end\n	return res.Instance:IsDescendantOf(target.Parent)\nend\n\nfunction Utils.ScreenCenter(): Vector2\n	local cam = Utils.Services.Workspace.CurrentCamera\n	local vs = cam and cam.ViewportSize or Vector2.new(1920, 1080)\n	return Vector2.new(vs.X / 2, vs.Y / 2)\nend\n\nreturn Utils\n\n|--!strict\n|-- UI.luau | liv4cheets - Internal | ClickGUI\n|-- Style refs: LinoriaLib tab/groupbox pattern (tabs + sections + controls),\n|-- custom Electron-ish dark shell. No external deps. Themes: Default (volt) / Onyx.\n\nlocal UI = {}\n\nlocal THEMES = {\n	Default = {\n		BG = Color3.fromRGB(16, 18, 24),\n		Panel = Color3.fromRGB(22, 25, 33),\n		Card = Color3.fromRGB(28, 32, 42),\n		Accent = Color3.fromRGB(198, 255, 62),\n		AccentText = Color3.fromRGB(12, 14, 18),\n		Text = Color3.fromRGB(245, 248, 240),\n		Dim = Color3.fromRGB(155, 165, 148),\n		Stroke = Color3.fromRGB(55, 65, 55),\n		ToggleOff = Color3.fromRGB(55, 62, 55),\n		Hover = Color3.fromRGB(35, 40, 52),\n	},\n	Onyx = {\n		BG = Color3.fromRGB(0, 0, 0),\n		Panel = Color3.fromRGB(8, 8, 8),\n		Card = Color3.fromRGB(14, 14, 14),\n		Accent = Color3.fromRGB(255, 255, 255),\n		AccentText = Color3.fromRGB(0, 0, 0),\n		Text = Color3.fromRGB(255, 255, 255),\n		Dim = Color3.fromRGB(180, 180, 180),\n		Stroke = Color3.fromRGB(50, 50, 50),\n		ToggleOff = Color3.fromRGB(55, 55, 55),\n		Hover = Color3.fromRGB(25, 25, 25),\n	},\n}\n\nlocal FONTS: { [string]: Enum.Font } = {\n	Gotham = Enum.Font.Gotham,\n	GothamMedium = Enum.Font.GothamMedium,\n	GothamBold = Enum.Font.GothamBold,\n	GothamBlack = Enum.Font.GothamBlack,\n	Code = Enum.Font.Code,\n	Montserrat = Enum.Font.Montserrat,\n	Arial = Enum.Font.Arial,\n}\n\nlocal function cref<T>(i: T): T\n	local f = (getgenv() :: any).cloneref\n	if type(f) == \"function\" then\n		local ok, o = pcall(f, i)\n		if ok and o then\n			return o\n		end\n	end\n	return i\nend\n\nlocal Players = cref(game:GetService(\"Players\"))\nlocal UIS = cref(game:GetService(\"UserInputService\"))\nlocal Tween = cref(game:GetService(\"TweenService\"))\n\nlocal function protect(gui: ScreenGui)\n	local gethui = (getgenv() :: any).gethui\n	if type(gethui) == \"function\" then\n		local ok, h = pcall(gethui)\n		if ok and h then\n			gui.Parent = h\n			return\n		end\n	end\n	pcall(function()\n		gui.Parent = game:GetService(\"CoreGui\")\n	end)\n	if gui.Parent == nil then\n		gui.Parent = Players.LocalPlayer:WaitForChild(\"PlayerGui\")\n	end\nend\n\nlocal function mk(class: string, props: any, parent: Instance?): any\n	local o: any = Instance.new(class)\n	for k, v in pairs(props) do\n		if k ~= \"Parent\" then\n			pcall(function()\n				o[k] = v\n			end)\n		end\n	end\n	o.Parent = parent\n	return o\nend\n\nlocal function animsOn(): boolean\n	local c = (getgenv() :: any).LIV4Config\n	if c and c.Misc and c.Misc.Anims == false then\n		return false\n	end\n	return true\nend\n\nfunction UI.New(): any\n	if (getgenv() :: any).LIV4UI then\n		pcall(function()\n			(getgenv() :: any).LIV4UI:Destroy()\n		end)\n	end\n	local C = (getgenv() :: any).LIV4Config\n	local T = THEMES[(C and C.Misc and C.Misc.Theme) or \"Default\"] or THEMES.Default\n\n	local gui = Instance.new(\"ScreenGui\")\n	gui.Name = \"liv4cheets\"\n	gui.ResetOnSpawn = false\n	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n	gui.IgnoreGuiInset = true\n	protect(gui);\n	(getgenv() :: any).LIV4UI = gui\n\n	local root = mk(\"Frame\", { Name = \"Root\", Size = UDim2.fromOffset(640, 440), Position = UDim2.new(0.5, -320, 0.5, -220), BackgroundColor3 = T.BG, BorderSizePixel = 0, Active = true }, gui)\n	mk(\"UICorner\", { CornerRadius = UDim.new(0, 12) }, root)\n	local rootStroke: any = mk(\"UIStroke\", { Color = T.Stroke, Thickness = 1 }, root)\n	do\n		local sc = mk(\"UIScale\", { Scale = 0.97 }, root)\n		local cfg0 = (getgenv() :: any).LIV4Config\n		if not cfg0 or cfg0.Misc.Anims ~= false then\n			pcall(function()\n				Tween:Create(sc, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1 }):Play()\n			end)\n		else\n			sc.Scale = 1\n		end\n	end\n\n	-- titlebar\n	local bar = mk(\"Frame\", { Name = \"PanelBG\", Size = UDim2.new(1, 0, 0, 42), BackgroundColor3 = T.Panel, BorderSizePixel = 0 }, root)\n	mk(\"UICorner\", { CornerRadius = UDim.new(0, 12) }, bar)\n	mk(\"Frame\", { Name = \"PanelBG\", Size = UDim2.new(1, 0, 0, 16), Position = UDim2.new(0, 0, 1, -16), BorderSizePixel = 0, BackgroundColor3 = T.Panel }, bar)\n\n	-- favicon\n	local fav = mk(\"Frame\", { Name = \"AccentBG\", Size = UDim2.fromOffset(26, 26), Position = UDim2.new(0, 14, 0.5, -13), BackgroundColor3 = T.Accent, BorderSizePixel = 0 }, bar)\n	mk(\"UICorner\", { CornerRadius = UDim.new(0, 8) }, fav)\n	mk(\"TextLabel\", { Name = \"AccentLabel\", Text = \"L4\", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, TextColor3 = T.AccentText, Font = Enum.Font.GothamBlack, TextSize = 13 }, fav)\n\n	mk(\"TextLabel\", { Name = \"MainText\", Text = \"liv4cheets - Internal\", Size = UDim2.new(0, 220, 1, 0), Position = UDim2.new(0, 48, 0, 0), BackgroundTransparency = 1, TextColor3 = T.Text, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left }, bar)\n	mk(\"TextLabel\", { Name = \"DimText\", Text = \"v1.0-internal\", Size = UDim2.new(0, 110, 1, 0), Position = UDim2.new(0, 232, 0, 0), BackgroundTransparency = 1, TextColor3 = T.Dim, Font = Enum.Font.Code, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left }, bar)\n	mk(\"TextLabel\", { Name = \"DimText\", Text = \"RShift\", Size = UDim2.new(0, 80, 1, 0), Position = UDim2.new(1, -90, 0, 0), BackgroundTransparency = 1, TextColor3 = T.Dim, Font = Enum.Font.Code, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Right }, bar)\n\n	-- sidebar + content\n	local side = mk(\"Frame\", { Name = \"PanelBG\", Size = UDim2.new(0, 160, 1, -42), Position = UDim2.new(0, 0, 0, 42), BackgroundColor3 = T.Panel, BorderSizePixel = 0 }, root)\n	mk(\"UIPadding\", { PaddingTop = UDim.new(0, 12), PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }, side)\n	mk(\"UIListLayout\", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, side)\n\n	local content = mk(\"Frame\", { Size = UDim2.new(1, -160, 1, -42), Position = UDim2.new(0, 160, 0, 42), BackgroundTransparency = 1 }, root)\n	mk(\"UIPadding\", { PaddingTop = UDim.new(0, 14), PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14), PaddingBottom = UDim.new(0, 14) }, content)\n\n	-- status bar\n	local foot = mk(\"TextLabel\", { Name = \"DimText\", Text = \"liv4cheets  •  connected\", Size = UDim2.new(1, -170, 0, 16), Position = UDim2.new(0, 166, 1, -24), BackgroundTransparency = 1, TextColor3 = T.Dim, Font = Enum.Font.Code, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left }, root)\n\n	-- drag\n	do\n		local drag, s, sp = false, nil, nil\n		bar.InputBegan:Connect(function(i)\n			if i.UserInputType == Enum.UserInputType.MouseButton1 then\n				drag, s, sp = true, i.Position, root.Position\n			end\n		end)\n		UIS.InputChanged:Connect(function(i)\n			if drag and i.UserInputType == Enum.UserInputType.MouseMovement and s then\n				local d = i.Position - s\n				root.Position = UDim2.new(sp.X.Scale, sp.X.Offset + d.X, sp.Y.Scale, sp.Y.Offset + d.Y)\n			end\n		end)\n		UIS.InputEnded:Connect(function(i)\n			if i.UserInputType == Enum.UserInputType.MouseButton1 then\n				drag = false\n			end\n		end)\n	end\n\n	local win: any = { Gui = gui, Root = root, _pages = {}, _tabBtns = {} }\n\n	function win:ApplyTheme(name: string)\n		local th = THEMES[name] or THEMES.Default\n		root.BackgroundColor3 = th.BG\n		rootStroke.Color = th.Stroke\n		for _, d in ipairs(root:GetDescendants()) do\n			if d.Name == \"PanelBG\" and d:IsA(\"GuiObject\") then\n				(d :: any).BackgroundColor3 = th.Panel\n			elseif d.Name == \"CardBG\" and d:IsA(\"GuiObject\") then\n				(d :: any).BackgroundColor3 = th.Card\n			elseif d.Name == \"AccentBG\" and d:IsA(\"GuiObject\") then\n				(d :: any).BackgroundColor3 = th.Accent\n			elseif d.Name == \"MainText\" and d:IsA(\"TextLabel\") then\n				(d :: any).TextColor3 = th.Text\n			elseif d.Name == \"DimText\" and d:IsA(\"TextLabel\") then\n				(d :: any).TextColor3 = th.Dim\n			elseif d.Name == \"AccentLabel\" then\n				(d :: any).TextColor3 = th.AccentText\n			end\n		end\n	end\n\n	function win:SetMenuFont(name: string)\n		local f = FONTS[name] or Enum.Font.GothamMedium\n		for _, d in ipairs(root:GetDescendants()) do\n			if d:IsA(\"TextLabel\") or d:IsA(\"TextButton\") or d:IsA(\"TextBox\") then\n				if (d :: any).Font ~= Enum.Font.Code then\n					(d :: any).Font = f\n				end\n			end\n		end\n	end\n\n	local function hover(btn: any, base: Color3)\n		if not animsOn() then\n			return\n		end\n		local hoverColor = base:Lerp(Color3.new(1, 1, 1), 0.12)\n		btn.MouseEnter:Connect(function()\n			pcall(function()\n				Tween:Create(btn, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = hoverColor }):Play()\n			end)\n		end)\n		btn.MouseLeave:Connect(function()\n			pcall(function()\n				Tween:Create(btn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = base }):Play()\n			end)\n		end)\n	end\n\n	function win:Tab(name: string): any\n		local btn = mk(\"TextButton\", { Name = \"CardBG\", Text = name, Size = UDim2.new(1, 0, 0, 36), BackgroundColor3 = T.Card, TextColor3 = T.Text, Font = Enum.Font.GothamMedium, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, AutoButtonColor = false, BorderSizePixel = 0 }, side)\n		mk(\"UICorner\", { CornerRadius = UDim.new(0, 10) }, btn)\n		mk(\"UIPadding\", { PaddingLeft = UDim.new(0, 20) }, btn)\n		local sel = mk(\"Frame\", { Name = \"AccentBG\", Size = UDim2.new(0, 3, 0, 22), Position = UDim2.new(0, 6, 0.5, -11), BackgroundColor3 = T.Accent, BorderSizePixel = 0, Visible = false }, btn)\n		mk(\"UICorner\", { CornerRadius = UDim.new(1, 0) }, sel)\n		hover(btn, T.Card)\n\n		local page = mk(\"ScrollingFrame\", { Size = UDim2.new(1, 0, 1, -8), BackgroundTransparency = 1, ScrollBarThickness = 2, CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y, Visible = false }, content)\n		mk(\"UIListLayout\", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, page)\n\n		local function select()\n			for _, p in ipairs(self._pages) do\n				(p :: any).Visible = false\n			end\n			for _, b in ipairs(self._tabBtns) do\n				((b :: any):FindFirstChildOfClass(\"Frame\") :: any).Visible = false\n				(b :: any).BackgroundColor3 = T.Card\n			end\n			page.Visible = true\n			sel.Visible = true\n			btn.BackgroundColor3 = T.Card:Lerp(T.Accent, 0.14)\n		end\n		btn.MouseButton1Click:Connect(select)\n		if #self._pages == 0 then\n			page.Visible = true\n			sel.Visible = true\n		end\n		table.insert(self._pages, page)\n		table.insert(self._tabBtns, btn)\n\n		local tab: any = {}\n		function tab:Section(t: string)\n			local row = mk(\"Frame\", { Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1 }, page)\n			mk(\"Frame\", { Name = \"AccentBG\", Size = UDim2.new(0, 3, 0, 14), Position = UDim2.new(0, 0, 0.5, -7), BackgroundColor3 = T.Accent, BorderSizePixel = 0 }, row)\n			mk(\"TextLabel\", { Name = \"DimText\", Text = string.upper(t), Size = UDim2.new(1, -12, 1, 0), Position = UDim2.new(0, 14, 0, 0), BackgroundTransparency = 1, TextColor3 = T.Dim, Font = Enum.Font.Code, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left }, row)\n		end\n		function tab:Toggle(label: string, default: boolean, cb: (boolean) -> ())\n			local st = default\n			local row = mk(\"Frame\", { Name = \"CardBG\", Size = UDim2.new(1, 0, 0, 38), BackgroundColor3 = T.Card, BorderSizePixel = 0 }, page)\n			mk(\"UICorner\", { CornerRadius = UDim.new(0, 10) }, row)\n			mk(\"TextLabel\", { Name = \"MainText\", Text = label, Size = UDim2.new(1, -72, 1, 0), Position = UDim2.new(0, 14, 0, 0), BackgroundTransparency = 1, TextColor3 = T.Text, Font = Enum.Font.GothamMedium, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left }, row)\n			local pill = mk(\"TextButton\", { Text = \"\", Size = UDim2.fromOffset(44, 24), Position = UDim2.new(1, -56, 0.5, -12), BackgroundColor3 = st and T.Accent or T.ToggleOff, AutoButtonColor = false, BorderSizePixel = 0 }, row)\n			mk(\"UICorner\", { CornerRadius = UDim.new(1, 0) }, pill)\n			local knob = mk(\"Frame\", { Size = UDim2.fromOffset(16, 16), Position = st and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 4, 0.5, -8), BackgroundColor3 = st and T.AccentText or Color3.new(1, 1, 1), BorderSizePixel = 0 }, pill)\n			mk(\"UICorner\", { CornerRadius = UDim.new(1, 0) }, knob)\n			local function sync(animate: boolean)\n				local c1 = st and T.Accent or T.ToggleOff\n				if animate and animsOn() then\n					pcall(function()\n						Tween:Create(pill, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = c1 }):Play()\n						Tween:Create(knob, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Position = st and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 4, 0.5, -8) }):Play()\n					end)\n				else\n					pill.BackgroundColor3 = c1\n					knob.Position = st and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 4, 0.5, -8)\n				end\n				knob.BackgroundColor3 = st and T.AccentText or Color3.new(1, 1, 1)\n			end\n			pill.MouseButton1Click:Connect(function()\n				st = not st\n				sync(true)\n				pcall(cb, st)\n			end)\n			sync(false)\n		end\n		function tab:Slider(label: string, min: number, max: number, default: number, cb: (number) -> ())\n			local val = default\n			local lab = mk(\"TextLabel\", { Name = \"MainText\", Text = label .. \"  \" .. tostring(math.round(val * 100) / 100), Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, TextColor3 = T.Text, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left }, page)\n			local track = mk(\"TextButton\", { Name = \"Track\", Text = \"\", Size = UDim2.new(1, 0, 0, 8), BackgroundColor3 = T.Stroke, AutoButtonColor = false, BorderSizePixel = 0 }, page)\n			mk(\"UICorner\", { CornerRadius = UDim.new(1, 0) }, track)\n			local fill = mk(\"Frame\", { Name = \"AccentBG\", Size = UDim2.new((val - min) / math.max(max - min, 0.001), 0, 1, 0), BackgroundColor3 = T.Accent, BorderSizePixel = 0 }, track)\n			mk(\"UICorner\", { CornerRadius = UDim.new(1, 0) }, fill)\n			local knobS = mk(\"Frame\", { Size = UDim2.fromOffset(14, 14), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new((val - min) / math.max(max - min, 0.001), 0, 0.5, 0), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 2 }, track)\n			mk(\"UICorner\", { CornerRadius = UDim.new(1, 0) }, knobS)\n			local function setX(x: number)\n				local p = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)\n				val = min + (max - min) * p\n				fill.Size = UDim2.new(p, 0, 1, 0)\n				knobS.Position = UDim2.new(p, 0, 0.5, 0)\n				lab.Text = label .. \"  \" .. tostring(math.round(val * 100) / 100)\n				pcall(cb, val)\n			end\n			track.MouseButton1Down:Connect(function(x)\n				setX(x)\n				local c\n				c = UIS.InputChanged:Connect(function(i)\n					if i.UserInputType == Enum.UserInputType.MouseMovement then\n						setX(i.Position.X)\n					end\n				end)\n				UIS.InputEnded:Wait()\n				if c then\n					c:Disconnect()\n				end\n			end)\n		end\n		function tab:Dropdown(label: string, values: { string }, default: string, cb: (string) -> ())\n			-- popup lives on the window root (never inside the scrolling canvas),\n			-- positioned under the button, with an outside-click catcher.\n			-- Pure dropdown list, no click-through cycling.\n			local sel = default\n			if not table.find(values, sel) then\n				sel = values[1]\n			end\n			local lab = mk(\"TextLabel\", { Name = \"MainText\", Text = label, Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, TextColor3 = T.Text, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left }, page)\n			local b = mk(\"TextButton\", { Name = \"CardBG\", Text = \"\", Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = T.Card, AutoButtonColor = false, BorderSizePixel = 0 }, page)\n			mk(\"UICorner\", { CornerRadius = UDim.new(0, 10) }, b)\n			mk(\"UIPadding\", { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14) }, b)\n			local bText = mk(\"TextLabel\", { Name = \"MainText\", Text = sel, Size = UDim2.new(1, -24, 1, 0), BackgroundTransparency = 1, TextColor3 = T.Text, Font = Enum.Font.Gotham, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left }, b)\n			mk(\"TextLabel\", { Name = \"DimText\", Text = \"▾\", Size = UDim2.new(0, 24, 1, 0), Position = UDim2.new(1, -24, 0, 0), BackgroundTransparency = 1, TextColor3 = T.Dim, Font = Enum.Font.Gotham, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Right }, b)\n			hover(b, T.Card)\n			b.MouseEnter:Connect(function()\n				if animsOn() then\n					pcall(function()\n						Tween:Create(b, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = T.Hover }):Play()\n					end)\n				end\n			end)\n			b.MouseLeave:Connect(function()\n				if animsOn() then\n					pcall(function()\n						Tween:Create(b, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = T.Card }):Play()\n					end)\n				end\n			end)\n			local catcher: any = nil\n			local pop: any = nil\n			local function close()\n				if catcher then\n					catcher:Destroy()\n					catcher = nil\n				end\n				if pop then\n					pop:Destroy()\n					pop = nil\n				end\n			end\n			b.MouseButton1Click:Connect(function()\n				if pop then\n					close()\n					return\n				end\n				local rp, bp = root.AbsolutePosition, b.AbsolutePosition\n				catcher = mk(\"TextButton\", { Text = \"\", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, AutoButtonColor = false, ZIndex = 90 }, root)\n				catcher.MouseButton1Click:Connect(close)\n				pop = mk(\"Frame\", { Name = \"CardBG\", Position = UDim2.new(0, bp.X - rp.X, 0, bp.Y - rp.Y + 36), Size = UDim2.new(0, b.AbsoluteSize.X, 0, math.min(#values * 30 + 12, 240)), BackgroundColor3 = T.Card, BorderSizePixel = 0, ZIndex = 91 }, root)\n				mk(\"UICorner\", { CornerRadius = UDim.new(0, 10) }, pop)\n				mk(\"UIStroke\", { Color = T.Stroke, Thickness = 1, Transparency = 0.5 }, pop)\n				mk(\"UIPadding\", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6), PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }, pop)\n				local scroll = mk(\"ScrollingFrame\", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, ScrollBarThickness = 2, CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y }, pop)\n				mk(\"UIListLayout\", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, scroll)\n				for _, v in ipairs(values) do\n					local mark = (v == sel) and \"✓  \" or \"    \"\n					local it = mk(\"TextButton\", { Text = mark .. v, Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, TextColor3 = (v == sel) and T.Accent or T.Text, Font = Enum.Font.Gotham, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, AutoButtonColor = false, BorderSizePixel = 0 }, scroll)\n					mk(\"UICorner\", { CornerRadius = UDim.new(0, 6) }, it)\n					mk(\"UIPadding\", { PaddingLeft = UDim.new(0, 10) }, it)\n					it.MouseButton1Click:Connect(function()\n						sel = v\n						bText.Text = v\n						lab.Text = label  .. \"  \" .. v\n						pcall(cb, v)\n						close()\n					end)\n				end\n			end)\n		end\n		function tab:Textbox(label: string, placeholder: string, default: string, cb: (string) -> ())\n			mk(\"TextLabel\", { Name = \"MainText\", Text = label, Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, TextColor3 = T.Text, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left }, page)\n			local box = mk(\"TextBox\", { Name = \"CardBG\", Text = default or \"\", PlaceholderText = placeholder or \"\", Size = UDim2.new(1, 0, 0, 32), BackgroundColor3 = T.Card, TextColor3 = T.Text, PlaceholderColor3 = T.Dim, Font = Enum.Font.Code, TextSize = 12, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left, BorderSizePixel = 0 }, page)\n			mk(\"UICorner\", { CornerRadius = UDim.new(0, 10) }, box)\n			mk(\"UIPadding\", { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14) }, box)\n			box.FocusLost:Connect(function(enter)\n				if enter then\n					pcall(cb, box.Text)\n				end\n			end)\n		end\n		function tab:Button(label: string, cb: () -> ())\n			local b = mk(\"TextButton\", { Name = \"AccentBG\", Text = label, Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = T.Accent, TextColor3 = T.AccentText, Font = Enum.Font.GothamBold, TextSize = 13, AutoButtonColor = false, BorderSizePixel = 0 }, page)\n			mk(\"UICorner\", { CornerRadius = UDim.new(0, 10) }, b)\n			local bs = mk(\"UIStroke\", { Color = T.Accent, Transparency = 0.5, Thickness = 1 }, b)\n			hover(b, T.Accent)\n			b.MouseButton1Click:Connect(function()\n				if animsOn() then\n					pcall(function()\n						Tween:Create(b, TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = UDim2.new(1, 0, 0, 32) }):Play()\n						task.wait(0.07)\n						Tween:Create(b, TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = UDim2.new(1, 0, 0, 34) }):Play()\n					end)\n				end\n				pcall(cb)\n			end)\n		end\n		return tab\n	end\n\n	local vis = true\n	UIS.InputBegan:Connect(function(i, gpe)\n		if gpe then\n			return\n		end\n		local cfg = (getgenv() :: any).LIV4Config\n		if i.KeyCode == ((cfg and cfg.Misc and cfg.Misc.ToggleKey) or Enum.KeyCode.RightShift) then\n			vis = not vis\n			root.Visible = vis\n		end\n		if i.KeyCode == ((cfg and cfg.Misc and cfg.Misc.UnloadKey) or Enum.KeyCode.End) then\n			pcall(function()\n				gui:Destroy()\n			end)\n		end\n	end)\n\n	return win\nend\n\nreturn UI\n\n--!strict\n-- Aimbot.luau | liv4cheets Internal | Combat tab\n-- v2: sticky target, velocity prediction, working wallcheck, dummy/NPC targets\n-- (dummies let you test in the shooting range — players-only can't aim there).\n\nlocal Aimbot = {}\n\nfunction Aimbot.Start(Utils, Config)\n	local S = Utils.Services\n	local Players, RS, UIS = S.Players, S.RunService, S.UserInputService\n\n	local function C()\n		return (getgenv() :: any).LIV4Config or (getgenv() :: any).RivalsConfig or Config.Current\n	end\n	local function combat()\n		local c = C()\n		if c.Combat then\n			return c.Combat\n		end\n		return { AimbotEnabled = c.Aimbot.Enabled, AimFOV = c.Aimbot.FOV, AimSmoothing = c.Aimbot.Smoothing, AimPart = c.Aimbot.HitPart }\n	end\n\n	local fov = Drawing.new(\"Circle\") :: any\n	fov.Thickness = 1\n	fov.Filled = false\n	local sFov = Drawing.new(\"Circle\") :: any\n	sFov.Thickness = 1\n	sFov.Filled = false\n	local dot = Drawing.new(\"Circle\") :: any\n	dot.Radius = 3\n	dot.Filled = true\n	dot.Visible = false\n\n	local sticky: BasePart? = nil\n\n	local function center(): Vector2\n		local cam = S.Workspace.CurrentCamera\n		local vs = cam and cam.ViewportSize or Vector2.new(1920, 1080)\n		return Vector2.new(vs.X / 2, vs.Y / 2)\n	end\n\n	local function partVelocity(part: BasePart): Vector3\n		local ok, v = pcall(function()\n			return (part :: any).AssemblyLinearVelocity\n		end)\n		if ok and typeof(v) == \"Vector3\" then\n			return v\n		end\n		local hrp = part.Parent and (part.Parent :: any):FindFirstChild(\"HumanoidRootPart\")\n		if hrp then\n			local ok2, v2 = pcall(function()\n				return (hrp :: any).AssemblyLinearVelocity\n			end)\n			if ok2 and typeof(v2) == \"Vector3\" then\n				return v2\n			end\n		end\n		return Vector3.zero\n	end\n\n	local function visible(from: Vector3, part: BasePart): boolean\n		local params = RaycastParams.new()\n		params.FilterType = Enum.RaycastFilterType.Exclude\n		local lp = Players.LocalPlayer\n		local ignore = { lp and lp.Character, workspace.CurrentCamera }\n		params.FilterDescendantsInstances = ignore\n		local dir = part.Position - from\n		local dist = dir.Magnitude\n		local res = S.Workspace:Raycast(from, dir, params)\n		if not res then\n			return true\n		end\n		-- If the raycast hit something, check if it's part of the target model\n		local hitModel = res.Instance:FindFirstAncestorOfClass(\"Model\")\n		if not hitModel then\n			return false\n		end\n		-- Allow hit if it's the target's model or a descendant\n		if hitModel == part.Parent then\n			return true\n		end\n		-- Check if we hit the actual part or a descendant of the target\n		if res.Instance == part or part:IsDescendantOf(hitModel) then\n			return true\n		end\n		return false\n	end\n\n	local function validChar(ch: Instance): boolean\n		local hum = (ch :: any):FindFirstChildOfClass(\"Humanoid\")\n		if not hum or hum.Health <= 0 then\n			return false\n		end\n		if Utils.IsAlly(ch) then\n			return false\n		end\n		return true\n	end\n\n	-- gather player chars + (optional) range dummies / NPC models\n	local function targets(wantDummies: boolean): { Model }\n		local out = {}\n		for _, p in ipairs(Players:GetPlayers()) do\n			if p ~= Players.LocalPlayer and p.Character and validChar(p.Character) then\n				table.insert(out, p.Character)\n			end\n		end\n		if wantDummies then\n			for _, d in ipairs(S.Workspace:GetDescendants()) do\n				if d:IsA(\"Model\") and d.Name:lower():find(\"dummy\") and validChar(d) then\n					table.insert(out, d)\n				end\n			end\n			-- generic fallback: models grouped under a \"Dummies\"/\"Targets\" folder\n			for _, n in ipairs({ \"Dummies\", \"Targets\", \"Bots\" }) do\n				local f = S.Workspace:FindFirstChild(n)\n				if f then\n					for _, m in ipairs(f:GetChildren()) do\n						if m:IsA(\"Model\") and validChar(m) then\n							table.insert(out, m)\n						end\n					end\n				end\n			end\n		end\n		return out\n	end\n\n	local function acquire(px: number, mode: string, wantDummies: boolean, wall: boolean): BasePart?\n		local cam = S.Workspace.CurrentCamera\n		if not cam then\n			return nil\n		end\n		-- sticky: keep current part while held and still good (with margin)\n		if sticky and sticky.Parent then\n			local m = (sticky :: BasePart).Parent\n			if m and validChar(m) then\n				local s, on = cam:WorldToViewportPoint((sticky :: BasePart).Position)\n				if on and (Vector2.new(s.X, s.Y) - center()).Magnitude < px * 1.5 then\n					if not wall or visible(cam.CFrame.Position, sticky) then\n						return sticky\n					end\n				end\n			end\n			sticky = nil\n		end\n		local cc = center()\n		-- Collect all valid targets with their screen positions\n		local candidates: { [BasePart]: number } = {}\n		for _, ch in ipairs(targets(wantDummies)) do\n			local part = Utils.GetHitPart(ch, mode)\n			if not part then\n				continue\n			end\n			local s, on = cam:WorldToViewportPoint(part.Position)\n			if not on then\n				continue\n			end\n			local d = (Vector2.new(s.X, s.Y) - cc).Magnitude\n			-- Only consider targets within FOV\n			if d <= px then\n				if wall and not visible(cam.CFrame.Position, part) then\n					continue\n				end\n				candidates[part] = d\n			end\n		end\n		-- Find the closest target\n		local best, bd = nil, px\n		for part, d in pairs(candidates) do\n			if d < bd then\n				bd, best = d, part\n			end\n		end\n		sticky = best\n		return best\n	end\n\n	-- ROOT FIX: default camera scripts overwrite Camera.CFrame every frame.\n	-- A plain RenderStepped:Connect runs BEFORE that update, so our aim gets\n	-- stomped (aimbot feels dead, esp. in first person). Camera.Value+1 runs\n	-- after, so our CFrame is the one that renders. Works 1st + 3rd person.\n	-- Improved: better target sorting, raycast visibility check, smoother lerp.\n	RS:BindToRenderStep(\"LIV4Aimbot\", Enum.RenderPriority.Camera.Value + 1, function()\n		local cb = combat()\n		local cam = S.Workspace.CurrentCamera\n		if not cam then\n			return\n		end\n		local cc = center()\n		fov.Visible = cb.AimbotEnabled\n		fov.Position = cc\n		fov.Radius = cb.AimFOV\n		sFov.Visible = cb.SilentEnabled\n		sFov.Position = cc\n		sFov.Radius = cb.SilentFOV\n		if not cb.AimbotEnabled then\n			sticky = nil\n			dot.Visible = false\n			return\n		end\n		if not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then\n			sticky = nil\n			dot.Visible = false\n			return\n		end\n		local t = acquire(cb.AimFOV, cb.AimPart, cb.TargetDummies ~= false, cb.WallCheck == true)\n		if not t then\n			dot.Visible = false\n			return\n		end\n		-- velocity prediction so fast strafes don't lag behind\n		local pred = cb.Prediction or 0\n		local aimPos = t.Position + partVelocity(t) * pred\n		local s, on = cam:WorldToViewportPoint(aimPos)\n		if on then\n			dot.Position = Vector2.new(s.X, s.Y)\n			dot.Visible = true\n		else\n			dot.Visible = false\n		end\n		-- Smooth camera movement toward aim point\n		local targetCF = CFrame.lookAt(cam.CFrame.Position, aimPos)\n		local lerpAmt = math.clamp(cb.AimSmoothing, 0.01, 1)\n		cam.CFrame = cam.CFrame:Lerp(targetCF, lerpAmt)\n	end)\n\n	function Aimbot.SilentTarget(): Vector3?\n		local cb = combat()\n		if not cb.SilentEnabled then\n			return nil\n		end\n		if math.random(100) > (cb.SilentChance or 100) then\n			return nil\n		end\n		local t = acquire(cb.SilentFOV, cb.AimPart, false, false)\n		if not t then\n			return nil\n		end\n		return t.Position + partVelocity(t) * (cb.Prediction or 0)\n	end\n\n	function Aimbot.Destroy()\n		pcall(function()\n			RS:UnbindFromRenderStep(\"LIV4Aimbot\")\n		end)\n		for _, d in ipairs({ fov, sFov, dot }) do\n			pcall(function()\n				d:Remove()\n			end)\n		end\n		sticky = nil\n	end\n	(getgenv() :: any).LIV4Aim = Aimbot\n\n	return Aimbot\nend\n\nreturn Aimbot\n\n--!strict\n-- SilentAim.luau | liv4cheets Internal | REAL silent aim (was a no-op before)\n-- Hooks Fighter.UseItem:FireServer and swaps the shot table's .position with\n-- the FOV target. Camera never moves, shots still land. Needs hookmetamethod,\n-- getnamecallmethod, checkcaller, newcclosure (present on Potassium/Wave).\n\nlocal SilentAim = {}\n\nfunction SilentAim.Start(Utils, Config, getTarget: () -> Vector3?)\n	local g = getgenv() :: any\n	if type(g.hookmetamethod) ~= \"function\"\n		or type(g.getnamecallmethod) ~= \"function\"\n		or type(g.checkcaller) ~= \"function\"\n		or type(g.newcclosure) ~= \"function\"\n	then\n		warn(\"[liv4] silent: executor lacks hook fns, silent aim unavailable\")\n		return SilentAim\n	end\n	if g.LIV4SilentHooked then\n		return SilentAim\n	end\n	g.LIV4SilentHooked = true\n\n	local old\n	old = g.hookmetamethod(game, \"__namecall\", g.newcclosure(function(self, ...)\n		local args = { ... }\n		local okM, method = pcall(g.getnamecallmethod)\n		if okM and method == \"FireServer\" then\n			local okC, isCallerLocal = pcall(g.checkcaller)\n			-- We want to intercept FireServer calls FROM the local player\n			-- (isCallerLocal == true means our client initiated the call).\n			if okC and isCallerLocal and typeof(self) == \"Instance\" then\n				local nm = \"\"\n				pcall(function()\n					nm = (self :: Instance).Name\n				end)\n				if nm == \"UseItem\" then\n					local c = g.LIV4Config or Config.Current\n					local cb = c and c.Combat\n					if cb and cb.SilentEnabled then\n						local okT, pos = pcall(getTarget)\n						if okT and typeof(pos) == \"Vector3\" then\n							for i, a in ipairs(args) do\n								if type(a) == \"table\" and typeof(a.position) == \"Vector3\" then\n									local cp = {}\n									for k, v in pairs(a) do\n										cp[k] = v\n									end\n									cp.position = pos\n									args[i] = cp\n									break\n								end\n							end\n						end\n					end\n				end\n			end\n		end\n		return old(self, unpack(args))\n	end))\n\n	return SilentAim\nend\n\nreturn SilentAim\n\n--!strict\n-- Triggerbot.luau | liv4cheets Internal | Combat tab\n\nlocal Triggerbot = {}\n\nfunction Triggerbot.Start(Utils, Config, shootFn: (() -> ())?)\n	local S = Utils.Services\n	local cb = function()\n		return (getgenv() :: any).LIV4Config or Config.Current\n	end\n	local params = RaycastParams.new()\n	params.FilterType = Enum.RaycastFilterType.Exclude\n	local HIT = { HitboxBody = true, HitboxHead = true, HitboxHands = true }\n\n	S.RunService.Heartbeat:Connect(function()\n		local c = cb()\n		local t = c.Combat or c.Triggerbot\n		local en = t.TriggerEnabled ~= nil and t.TriggerEnabled or t.Enabled\n		if not en then\n			return\n		end\n		if not S.UserInputService:IsKeyDown(t.TriggerKey or Enum.KeyCode.T) then\n			return\n		end\n		local cam = S.Workspace.CurrentCamera\n		if not cam then\n			return\n		end\n		local lp = S.Players.LocalPlayer\n		params.FilterDescendantsInstances = { lp and lp.Character }\n		local res = S.Workspace:Raycast(cam.CFrame.Position, cam.CFrame.LookVector * 600, params)\n		if not res or not HIT[res.Instance.Name] then\n			return\n		end\n		local m = res.Instance:FindFirstAncestorOfClass(\"Model\")\n		if not m then\n			return\n		end\n		local h = m:FindFirstChildOfClass(\"Humanoid\")\n		if not h or h.Health <= 0 or Utils.IsAlly(m) then\n			return\n		end\n		task.delay((t.TriggerDelay or 40) / 1000, function()\n			if shootFn then\n				pcall(shootFn)\n			else\n				pcall(function()\n					mouse1click()\n				end)\n			end\n		end)\n	end)\n	return Triggerbot\nend\n\nreturn Triggerbot\n\n--!strict\n-- ESP.luau | liv4cheets Internal | Visual tab\n-- ROOT FIX for stuck drawings: central registry + destroy on teleport/leave/remove/unload.\n-- Drawings are overlay-level: they survive teleports unless WE remove them.\n\nlocal ESP = {}\n\nfunction ESP.Start(Utils, Config)\n	local S = Utils.Services\n	local Players, RS = S.Players, S.RunService\n	local function C()\n		return (getgenv() :: any).LIV4Config or Config.Current\n	end\n	local function V()\n		local c = C()\n		return c.Visual or {}\n	end\n\n	local allDrawings: { any } = {}\n	local conns: { RBXScriptConnection } = {}\n	local function track(d: any)\n		table.insert(allDrawings, d)\n		return d\n	end\n	local function on(c: RBXScriptConnection)\n		table.insert(conns, c)\n	end\n\n	type E = { box: any, fill: any, name: any, dist: any, hpBG: any, hp: any, skel: { any } }\n	local cache: { [Player]: E } = {}\n	local function get(p: Player): E\n		local e = cache[p]\n		if e then\n			return e\n		end\n		local function sq(f: boolean): any\n			return track(Drawing.new(\"Square\") :: any)\n		end\n		local function tx(): any\n			local t = track(Drawing.new(\"Text\") :: any) :: any\n			t.Center = true\n			t.Outline = true\n			return t\n		end\n		local b1 = sq(false)\n		b1.Filled = false\n		b1.Thickness = 1\n		local f1 = sq(true)\n		f1.Filled = true\n		local n1, d1 = tx(), tx()\n		local bg, hp = sq(true), sq(true)\n		bg.Filled = true\n		hp.Filled = true\n		local sk: { any } = {}\n		for _ = 1, 6 do\n			local l = track(Drawing.new(\"Line\") :: any) :: any\n			l.Thickness = 1\n			table.insert(sk, l)\n		end\n		e = { box = b1, fill = f1, name = n1, dist = d1, hpBG = bg, hp = hp, skel = sk }\n		hide(e)\n		cache[p] = e\n		return e\n	end\n	function hide(e: E)\n		e.box.Visible = false\n		e.fill.Visible = false\n		e.name.Visible = false\n		e.dist.Visible = false\n		e.hpBG.Visible = false\n		e.hp.Visible = false\n		for _, l in ipairs(e.skel) do\n			l.Visible = false\n		end\n	end\n	local function hideAll()\n		for _, e in pairs(cache) do\n			hide(e)\n		end\n	end\n	local function dropPlayer(p: Player)\n		local e = cache[p]\n		if not e then\n			return\n		end\n		hide(e)\n		pcall(function()\n			e.box:Remove()\n		end)\n		pcall(function()\n			e.fill:Remove()\n		end)\n		pcall(function()\n			e.name:Remove()\n		end)\n		pcall(function()\n			e.dist:Remove()\n		end)\n		pcall(function()\n			e.hpBG:Remove()\n		end)\n		pcall(function()\n			e.hp:Remove()\n		end)\n		for _, l in ipairs(e.skel) do\n			pcall(function()\n				l:Remove()\n			end)\n		end\n		cache[p] = nil\n	end\n\n	function ESP.Destroy()\n		for _, c in ipairs(conns) do\n			pcall(function()\n				c:Disconnect()\n			end)\n		end\n		table.clear(conns)\n		for _, e in pairs(cache) do\n			hide(e)\n		end\n		for _, d in ipairs(allDrawings) do\n			pcall(function()\n				d:Remove()\n			end)\n		end\n		table.clear(allDrawings)\n		table.clear(cache)\n	end\n	-- root fix: nuke overlay the moment we leave / teleport / get unloaded\n	on(game:GetService(\"TeleportService\").TeleportInit:Connect(function()\n		hideAll()\n		ESP.Destroy()\n	end))\n	on(Players.PlayerRemoving:Connect(dropPlayer))\n	do\n		local lp = Players.LocalPlayer\n		if lp then\n			on(lp.OnTeleport:Connect(function()\n				hideAll()\n				ESP.Destroy()\n			end))\n			if lp.Character then\n				on(lp.CharacterRemoving:Connect(hideAll))\n			end\n			on(lp.CharacterAdded:Connect(function(ch)\n				ch.AncestryChanged:Connect(function()\n					if not ch:IsDescendantOf(game) then\n						hideAll()\n					end\n				end)\n			end))\n		end\n	end\n	on(Players.PlayerAdded:Connect(function(p)\n		on(p.CharacterRemoving:Connect(function()\n			local e = cache[p]\n			if e then\n				hide(e)\n			end\n		end))\n	end))\n	for _, p in ipairs(Players:GetPlayers()) do\n		if p ~= Players.LocalPlayer then\n			on(p.CharacterRemoving:Connect(function()\n				local e = cache[p]\n				if e then\n					hide(e)\n				end\n			end))\n		end\n	end\n\n	local function chamsOn(ch: Model, color: Color3, on: boolean)\n		local h = ch and ch:FindFirstChild(\"LIV4Chams\")\n		if on then\n			if not h and ch:IsDescendantOf(game) then\n				local hl = Instance.new(\"Highlight\")\n				hl.Name = \"LIV4Chams\"\n				hl.FillColor = color\n				hl.FillTransparency = 0.5\n				hl.OutlineTransparency = 1\n				hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop\n				hl.Parent = ch\n			end\n		elseif h then\n			h:Destroy()\n		end\n	end\n\n	on(RS.RenderStepped:Connect(function()\n		local v = V()\n		local cam = S.Workspace.CurrentCamera\n		if not cam then\n			hideAll()\n			return\n		end\n		if not v.ESPEnabled then\n			hideAll()\n			return\n		end\n		for _, p in ipairs(Players:GetPlayers()) do\n			if p == Players.LocalPlayer then\n				continue\n			end\n			local e = get(p)\n			local ch = p.Character\n			-- root fix: character gone from hierarchy (teleport/leave) -> drop, don't draw stale box\n			if not ch or not ch:IsDescendantOf(game) then\n				hide(e)\n				continue\n			end\n			local hrp = ch:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n			local hum = ch:FindFirstChildOfClass(\"Humanoid\")\n			if not hrp or not hum or hum.Health <= 0 then\n				hide(e)\n				chamsOn(ch, Color3.new(1, 1, 1), false)\n				continue\n			end\n			if Utils.IsAlly(ch) and not v.ShowTeam then\n				hide(e)\n				chamsOn(ch, Color3.new(1, 1, 1), false)\n				continue\n			end\n			chamsOn(ch, v.ChamsColor or Color3.fromRGB(198, 255, 62), v.Chams)\n			local d3 = (hrp.Position - cam.CFrame.Position).Magnitude\n			if d3 > (v.MaxDistance or 2000) then\n				hide(e)\n				continue\n			end\n			local t, onT = cam:WorldToViewportPoint((hrp.CFrame * CFrame.new(0, 2.5, 0)).Position)\n			local b, onB = cam:WorldToViewportPoint((hrp.CFrame * CFrame.new(0, -3.5, 0)).Position)\n			if not onT or not onB then\n				hide(e)\n				continue\n			end\n			local h = math.max(12, (Vector2.new(t.X, t.Y) - Vector2.new(b.X, b.Y)).Magnitude)\n			local w = h * 0.6\n			local x, y = b.X - w / 2, b.Y - h\n			local ts = v.GameFontSize or v.TextSize or 13\n			local hbT = v.HealthBarThickness or 4\n\n			if v.FilledBox then\n				e.fill.Size = Vector2.new(w, h)\n				e.fill.Position = Vector2.new(x, y)\n				e.fill.Transparency = 0.5\n				e.fill.Visible = true\n				e.box.Size = Vector2.new(w, h)\n				e.box.Position = Vector2.new(x, y)\n				e.box.Visible = v.Box\n			elseif v.FilledNoOutline then\n				e.fill.Size = Vector2.new(w, h)\n				e.fill.Position = Vector2.new(x, y)\n				e.fill.Transparency = 0.5\n				e.fill.Visible = true\n				e.box.Visible = false\n			else\n				e.fill.Visible = false\n				e.box.Size = Vector2.new(w, h)\n				e.box.Position = Vector2.new(x, y)\n				e.box.Visible = v.Box\n			end\n\n			e.name.Size = ts\n			e.name.Text = p.Name\n			e.name.Position = Vector2.new(b.X, y - ts - 2)\n			e.name.Visible = v.Name\n			e.dist.Size = ts\n			e.dist.Text = \"[\" .. math.round(d3) .. \"m]\"\n			e.dist.Position = Vector2.new(b.X, b.Y + 2)\n			e.dist.Visible = v.Distance\n\n			if v.HealthBar then\n				local r = math.clamp(hum.Health / hum.MaxHealth, 0, 1)\n				e.hpBG.Size = Vector2.new(hbT, h)\n				e.hpBG.Position = Vector2.new(x - hbT - 2, y)\n				e.hpBG.Visible = true\n				e.hp.Size = Vector2.new(hbT, h * r)\n				e.hp.Position = Vector2.new(x - hbT - 2, y + h * (1 - r))\n				e.hp.Color = Color3.fromRGB(255 - math.round(255 * r), math.round(255 * r), 60)\n				e.hp.Visible = true\n			else\n				e.hpBG.Visible = false\n				e.hp.Visible = false\n			end\n\n			if v.Skeleton then\n				local head = ch:FindFirstChild(\"Head\")\n				local la = ch:FindFirstChild(\"LeftHand\") or ch:FindFirstChild(\"LeftUpperArm\")\n				local ra = ch:FindFirstChild(\"RightHand\") or ch:FindFirstChild(\"RightUpperArm\")\n				local ll = ch:FindFirstChild(\"LeftFoot\") or ch:FindFirstChild(\"LeftLowerLeg\")\n				local rl = ch:FindFirstChild(\"RightFoot\") or ch:FindFirstChild(\"RightLowerLeg\")\n				local pts = { head, hrp, la, ra, ll, rl }\n				local sp: { Vector2? } = {}\n				for i, part in ipairs(pts) do\n					if part and (part :: any).Position then\n						local s2, on2 = cam:WorldToViewportPoint((part :: any).Position)\n						sp[i] = on2 and Vector2.new(s2.X, s2.Y) or nil\n					end\n				end\n				local pairs = { { 1, 2 }, { 2, 3 }, { 2, 4 }, { 2, 5 }, { 2, 6 } }\n				for i, pr in ipairs(pairs) do\n					local a, bb = sp[pr[1]], sp[pr[2]]\n					local L = e.skel[i]\n					if a and bb then\n						L.From, L.To, L.Visible = a, bb, true\n					else\n						L.Visible = false\n					end\n				end\n				for i = 6, #e.skel do\n					e.skel[i].Visible = false\n				end\n			else\n				for _, L in ipairs(e.skel) do\n					L.Visible = false\n				end\n			end\n		end\n	end))\n	-- expose for Main unload path\n	(getgenv() :: any).LIV4ESP = ESP\n	return ESP\nend\n\nreturn ESP\n\n--!strict\n-- Movement.luau | liv4cheets Internal | Exploits tab (fly/noclip)\n\nlocal Movement = {}\n\nfunction Movement.Start(Utils, Config)\n	local S = Utils.Services\n	local function C()\n		return (getgenv() :: any).LIV4Config or Config.Current\n	end\n	S.RunService.Heartbeat:Connect(function()\n		local c = C()\n		local ex = c.Exploits or c.Movement\n		if not ex then\n			return\n		end\n		local lp = S.Players.LocalPlayer\n		local ch = lp and lp.Character\n		local r = ch and ch:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n		local h = ch and ch:FindFirstChildOfClass(\"Humanoid\")\n		if not r or not h then\n			return\n		end\n		local fly = ex.Fly\n		local spd = ex.FlySpeed or 60\n		if fly then\n			h.PlatformStand = true\n			local cam = S.Workspace.CurrentCamera\n			local m = Vector3.zero\n			local UIS = S.UserInputService\n			if UIS:IsKeyDown(Enum.KeyCode.W) then\n				m += cam.CFrame.LookVector\n			end\n			if UIS:IsKeyDown(Enum.KeyCode.S) then\n				m -= cam.CFrame.LookVector\n			end\n			if UIS:IsKeyDown(Enum.KeyCode.A) then\n				m -= cam.CFrame.RightVector\n			end\n			if UIS:IsKeyDown(Enum.KeyCode.D) then\n				m += cam.CFrame.RightVector\n			end\n			if UIS:IsKeyDown(Enum.KeyCode.Space) then\n				m += Vector3.yAxis\n			end\n			r.AssemblyLinearVelocity = if m.Magnitude > 0 then m.Unit * spd else Vector3.zero\n			r.AssemblyAngularVelocity = Vector3.zero\n		end\n	end)\n	S.RunService.Stepped:Connect(function()\n		local c = C()\n		local ex = c.Exploits or c.Movement\n		if not ex or not ex.Noclip then\n			return\n		end\n		local ch = S.Players.LocalPlayer and S.Players.LocalPlayer.Character\n		if not ch then\n			return\n		end\n		for _, p in ipairs(ch:GetDescendants()) do\n			if p:IsA(\"BasePart\") then\n				p.CanCollide = false\n			end\n		end\n	end)\n	return Movement\nend\n\nreturn Movement\n\n--!strict\n-- Effects.luau | liv4cheets Internal | hitmarker visual (wired to Visual tab)\n\nlocal Effects = {}\n\nfunction Effects.Start(Utils, Config)\n	local S = Utils.Services\n	function Effects.Hitmarker(ch: Model, dmg: number?)\n		local c = (getgenv() :: any).LIV4Config or Config.Current\n		local v = c.Visual\n		if v and v.ESPEnabled == false then\n		end\n		local head = ch and (ch:FindFirstChild(\"Head\") or ch:FindFirstChild(\"HumanoidRootPart\"))\n		if not head then\n			return\n		end\n		local g = Instance.new(\"BillboardGui\")\n		g.Size = UDim2.fromScale(1, 1)\n		g.AlwaysOnTop = true\n		g.Adornee = head\n		g.Parent = ch\n		local l = Instance.new(\"TextLabel\")\n		l.Size = UDim2.fromScale(1, 1)\n		l.BackgroundTransparency = 1\n		l.Text = tostring(math.round(dmg or 10))\n		l.Font = Enum.Font.GothamBlack\n		l.TextSize = 42\n		l.TextStrokeTransparency = 0\n		l.Parent = g\n		task.delay(0.8, function()\n			pcall(function()\n				g:Destroy()\n			end)\n		end)\n	end\n	return Effects\nend\n\nreturn Effects\n\n--!strict\n-- Ragebot.luau | liv4cheets Internal | Combat tab | HIGH BAN RISK, off by default\n\nlocal Ragebot = {}\n\nfunction Ragebot.Start(Utils, Config)\n	local S = Utils.Services\n	local function C()\n		return (getgenv() :: any).LIV4Config or Config.Current\n	end\n	local function R()\n		local c = C()\n		return c.Combat or c.Ragebot\n	end\n	local n = 0\n	local remote: RemoteEvent? = nil\n	pcall(function()\n		local rs = S.ReplicatedStorage:WaitForChild(\"Remotes\", 2)\n		local f = rs and (rs :: any):WaitForChild(\"Fighter\", 2)\n		remote = f and (f :: any):WaitForChild(\"UseItem\", 2)\n	end)\n	S.RunService.Heartbeat:Connect(function()\n		local r = R()\n		local en = r.RageEnabled ~= nil and r.RageEnabled or r.Enabled\n		local vs = r.RageVoidSpam ~= nil and r.RageVoidSpam or r.VoidSpam\n		if not en or not vs or not remote then\n			return\n		end\n		local my = S.Players.LocalPlayer and S.Players.LocalPlayer.Character\n		if not my or not my:FindFirstChild(\"EquippedItem\") then\n			return\n		end\n		local cam = S.Workspace.CurrentCamera\n		local best, bd = nil, math.huge\n		for _, p in ipairs(S.Players:GetPlayers()) do\n			if p == S.Players.LocalPlayer then\n				continue\n			end\n			local ch = p.Character\n			if not ch or not Utils.IsAlive(ch) or Utils.IsAlly(ch) then\n				continue\n			end\n			local hrp = ch:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n			if hrp and cam then\n				local d = (hrp.Position - cam.CFrame.Position).Magnitude\n				if d < bd then\n					bd, best = d, ch\n				end\n			end\n		end\n		if not best then\n			return\n		end\n		local hb = Utils.GetHitPart(best, \"Head\")\n		if not hb then\n			return\n		end\n		n += 1\n		pcall(function()\n			(remote :: RemoteEvent):FireServer({ id = game:GetService(\"HttpService\"):GenerateGUID(false), item = r.RageWeapon or r.WeaponName, position = hb.Position, attackNum = n })\n		end)\n	end)\n	return Ragebot\nend\n\nreturn Ragebot\n\n--!strict\n-- Spoofer.luau | liv4cheets Internal | Exploits tab\n-- Client-visual only unless the game trusts the client. Server values revert on respawn/round.\n\nlocal Spoofer = {}\nlocal animTrack: AnimationTrack? = nil\n\nfunction Spoofer.Avatar(userIdStr: string): string\n	local id = tonumber(userIdStr)\n	if not id then\n		return \"invalid user id\"\n	end\n	local lp = game:GetService(\"Players\").LocalPlayer\n	local ch = lp and lp.Character\n	local hum = ch and ch:FindFirstChildOfClass(\"Humanoid\")\n	if not hum then\n		return \"no character\"\n	end\n	local ok, desc = pcall(function()\n		return game:GetService(\"Players\"):GetHumanoidDescriptionFromUserId(id)\n	end)\n	if not ok or not desc then\n		return \"bad user id\"\n	end\n	pcall(function()\n		hum:ApplyDescription(desc)\n	end)\n	return \"applied \" .. tostring(id)\nend\n\nlocal function setLeaderstat(name: string, value: string): string\n	local v = tonumber(value)\n	if not v then\n		return \"invalid number\"\n	end\n	local lp = game:GetService(\"Players\").LocalPlayer\n	local ls = lp and lp:FindFirstChild(\"leaderstats\")\n	if ls then\n		for _, s in ipairs(ls:GetChildren()) do\n			if string.lower(s.Name) == string.lower(name) or string.find(string.lower(s.Name), string.lower(name), 1, true) then\n				pcall(function()\n					if s:IsA(\"IntValue\") or s:IsA(\"NumberValue\") then\n						(s :: any).Value = v\n					elseif s:IsA(\"StringValue\") then\n						(s :: any).Value = tostring(v)\n					end\n				end)\n			end\n		end\n	end\n	-- also overwrite on-screen labels (visual)\n	local n = 0\n	for _, g in ipairs(lp.PlayerGui:GetDescendants()) do\n		if g:IsA(\"TextLabel\") and string.find(string.lower(g.Text), string.lower(name), 1, true) then\n			g.Text = string.gsub(g.Text, \"%d+\", tostring(v))\n			n += 1\n			if n > 6 then\n				break\n			end\n		end\n	end\n	return \"spoofed \" .. name .. \" -> \" .. tostring(v) .. \" (visual)\"\nend\n\nfunction Spoofer.Level(v: string)\n	return setLeaderstat(\"level\", v)\nend\nfunction Spoofer.Streak(v: string)\n	local a = setLeaderstat(\"streak\", v)\n	local b = setLeaderstat(\"win\", v)\n	return a .. \" / \" .. b\nend\nfunction Spoofer.Board(v: string)\n	return setLeaderstat(\"win\", v)\nend\nfunction Spoofer.Ranked(v: string)\n	return setLeaderstat(\"rank\", v)\nend\n\nfunction Spoofer.PlayAnim(assetStr: string): string\n	local id = tonumber(assetStr)\n	if not id then\n		return \"invalid asset id\"\n	end\n	local lp = game:GetService(\"Players\").LocalPlayer\n	local ch = lp and lp.Character\n	local hum = ch and ch:FindFirstChildOfClass(\"Humanoid\")\n	local anim = hum and hum:FindFirstChildOfClass(\"Animator\") or hum\n	if not hum then\n		return \"no humanoid\"\n	end\n	if animTrack then\n		pcall(function()\n			(animTrack :: AnimationTrack):Stop()\n		end)\n		animTrack = nil\n	end\n	local a = Instance.new(\"Animation\")\n	a.AnimationId = \"rbxassetid://\" .. tostring(id)\n	local ok, tr = pcall(function()\n		return (hum :: Humanoid):LoadAnimation(a)\n	end)\n	if not ok or not tr then\n		return \"load failed\"\n	end\n	animTrack = tr\n	pcall(function()\n		(animTrack :: AnimationTrack):Play()\n	end)\n	return \"playing \" .. tostring(id)\nend\n\nfunction Spoofer.StopAnim(): string\n	if animTrack then\n		pcall(function()\n			(animTrack :: AnimationTrack):Stop()\n		end)\n		animTrack = nil\n		return \"stopped\"\n	end\n	return \"nothing playing\"\nend\n\nreturn Spoofer\n\n--!strict\n-- ConfigManager.luau | liv4cheets Internal | Configs tab | clean JSON stored locally\n-- Executor FS (writefile/readfile/listfiles) + mirrors to Documents folder when possible.\n\nlocal ConfigManager = {}\nlocal HS = game:GetService(\"HttpService\")\nlocal FOLDER = \"liv4cheets_configs\"\n\nlocal function hasFS(): boolean\n	local g = getgenv() :: any\n	return type(g.writefile) == \"function\" and type(g.readfile) == \"function\" and type(g.listfiles) == \"function\"\nend\n\nfunction ConfigManager.Folder(): string\n	return FOLDER\nend\n\nfunction ConfigManager.Ensure()\n	if not hasFS() then\n		return\n	end\n	pcall(function()\n		(getgenv() :: any).makefolder(FOLDER)\n	end)\nend\n\nlocal function serializable(v: any): any\n	if typeof(v) == \"EnumItem\" then\n		return { __enum = tostring(v.EnumType) .. \".\" .. tostring(v.Name) }\n	elseif typeof(v) == \"Color3\" then\n		return { __color = { math.round(v.R * 255), math.round(v.G * 255), math.round(v.B * 255) } }\n	elseif type(v) == \"table\" then\n		local o = {}\n		for k, vv in pairs(v) do\n			o[k] = serializable(vv)\n		end\n		return o\n	elseif type(v) == \"number\" or type(v) == \"string\" or type(v) == \"boolean\" then\n		return v\n	end\n	return nil\nend\n\nlocal function restore(v: any): any\n	if type(v) == \"table\" then\n		if v.__enum then\n			local s: string = v.__enum\n			local a, b = string.match(s, \"Enum%.(%w+)%.(%w+)\")\n			local ok, e = pcall(function()\n				return (Enum :: any)[a][b]\n			end)\n			return ok and e or nil\n		end\n		if v.__color then\n			return Color3.fromRGB(v.__color[1], v.__color[2], v.__color[3])\n		end\n		local o = {}\n		for k, vv in pairs(v) do\n			o[k] = restore(vv)\n		end\n		return o\n	end\n	return v\nend\n\nfunction ConfigManager.List(): { string }\n	ConfigManager.Ensure()\n	if not hasFS() then\n		return {}\n	end\n	local ok, files = pcall(function()\n		return (getgenv() :: any).listfiles(FOLDER)\n	end)\n	if not ok or type(files) ~= \"table\" then\n		return {}\n	end\n	local out = {}\n	for _, f in ipairs(files) do\n		local n = string.match(f, \"([^\\\\/]+)%.json$\")\n		if n then\n			table.insert(out, n)\n		end\n	end\n	return out\nend\n\nfunction ConfigManager.Save(name: string): string\n	if not hasFS() then\n		return \"no FS (writefile missing)\"\n	end\n	name = string.gsub(name or \"\", \"[^%w%-%_]\", \"\")\n	if #name == 0 then\n		return \"invalid name\"\n	end\n	ConfigManager.Ensure()\n	local c = (getgenv() :: any).LIV4Config\n	local ok, j = pcall(function()\n		return HS:JSONEncode(serializable(c))\n	end)\n	if not ok then\n		return \"encode failed\"\n	end\n	local ok2, err = pcall(function()\n		(getgenv() :: any).writefile(FOLDER .. \"/\" .. name .. \".json\", j)\n	end)\n	return ok2 and (\"saved \" .. name) or (\"save failed: \" .. tostring(err))\nend\n\nfunction ConfigManager.Load(name: string): string\n	if not hasFS() then\n		return \"no FS (readfile missing)\"\n	end\n	local ok, j = pcall(function()\n		return (getgenv() :: any).readfile(FOLDER .. \"/\" .. name .. \".json\")\n	end)\n	if not ok then\n		return \"read failed\"\n	end\n	local ok2, t = pcall(function()\n		return HS:JSONDecode(j)\n	end)\n	if not ok2 or type(t) ~= \"table\" then\n		return \"decode failed\"\n	end\n	(getgenv() :: any).LIV4Config = restore(t);\n	(getgenv() :: any).RivalsConfig = (getgenv() :: any).LIV4Config\n	return \"loaded \" .. name .. \" (re-execute to apply fully)\"\nend\n\nfunction ConfigManager.Delete(name: string): string\n	if not hasFS() then\n		return \"no FS\"\n	end\n	pcall(function()\n		(getgenv() :: any).delfile(FOLDER .. \"/\" .. name .. \".json\")\n	end)\n	return \"deleted \" .. name\nend\n\nreturn ConfigManager\n\n--!strict\n-- SkinChanger.luau | liv4cheets Internal | YOU-ONLY visuals\n-- Others still see your previously equipped skins/wraps/charms/finishers.\n-- Applies locally to ViewModel + worldmodel clones, reapplies on equip/respawn.\n-- If actual Rivals skin paths differ, run Dump() once and send output back to refine.\n\nlocal SkinChanger = {}\n\nlocal applied: { [string]: any } = {}\nlocal conns: { RBXScriptConnection } = {}\n\nlocal function lp()\n	return game:GetService(\"Players\").LocalPlayer\nend\n\nlocal function myChar()\n	local p = lp()\n	return p and p.Character or nil\nend\n\n-- Try to find the live weapon models to repaint: EquippedItem ViewModel + character tool parts\nlocal function weaponModels(): { Instance }\n	local out = {}\n	local ch = myChar()\n	if not ch then\n		return out\n	end\n	local eq = ch:FindFirstChild(\"EquippedItem\")\n	if eq then\n		local vm = (eq :: any).ViewModel or eq:FindFirstChild(\"ViewModel\")\n		if vm then\n			table.insert(out, vm)\n		end\n		table.insert(out, eq)\n	end\n	for _, d in ipairs(ch:GetChildren()) do\n		if d:IsA(\"Model\") and (d.Name == \"ViewModel\" or string.find(d.Name, \"Weapon\", 1, true)) then\n			table.insert(out, d)\n		end\n	end\n	local cam = workspace.CurrentCamera\n	if cam then\n		local cvm = cam:FindFirstChild(\"ViewModel\")\n		if cvm then\n			table.insert(out, cvm)\n		end\n	end\n	return out\nend\n\nlocal function paint(model: Instance, color: Color3?, material: Enum.Material?)\n	for _, d in ipairs(model:GetDescendants()) do\n		if d:IsA(\"BasePart\") and not d.Name:lower():find(\"hitbox\") then\n			pcall(function()\n				if color then\n					(d :: BasePart).Color = color\n				end\n				if material then\n					(d :: BasePart).Material = material\n				end\n			end)\n		end\n	end\nend\n\nlocal function clearCharms()\n	local ch = myChar()\n	if not ch then\n		return\n	end\n	for _, m in ipairs(weaponModels()) do\n		local old = m:FindFirstChild(\"LIV4Charm\")\n		if old then\n			old:Destroy()\n		end\n	end\nend\n\nfunction SkinChanger.ApplySkin(weaponName: string, skinName: string, hexColor: string): string\n	local c = Color3.fromRGB(198, 255, 62)\n	if hexColor and #hexColor >= 6 then\n		pcall(function()\n			local h = string.gsub(hexColor, \"#\", \"\")\n			c = Color3.fromRGB(tonumber(h:sub(1, 2), 16) or 198, tonumber(h:sub(3, 4), 16) or 255, tonumber(h:sub(5, 6), 16) or 62)\n		end)\n	end\n	applied[\"skin:\" .. weaponName] = { skin = skinName, color = c }\n	for _, m in ipairs(weaponModels()) do\n		if #weaponName == 0 or string.lower(m:GetFullName()):find(string.lower(weaponName), 1, true) or m.Name == weaponName or m.Parent and (m.Parent :: any).Name == weaponName then\n			paint(m, c, nil)\n		end\n	end\n	-- fallback: paint current weapon regardless of name match (you-only)\n	if #weaponModels() > 0 and #weaponName > 0 then\n		local anyMatch = false\n		for _, m in ipairs(weaponModels()) do\n			if m.Name == weaponName then\n				anyMatch = true\n			end\n		end\n		if not anyMatch then\n			for _, m in ipairs(weaponModels()) do\n				paint(m, c, nil)\n			end\n		end\n	end\n	return \"skin applied locally: \" .. weaponName .. \" / \" .. skinName\nend\n\nfunction SkinChanger.ApplyWrap(hexColor: string): string\n	local c = Color3.fromRGB(198, 255, 62)\n	pcall(function()\n		local h = string.gsub(hexColor or \"\", \"#\", \"\")\n		if #h >= 6 then\n			c = Color3.fromRGB(tonumber(h:sub(1, 2), 16) or 198, tonumber(h:sub(3, 4), 16) or 255, tonumber(h:sub(5, 6), 16) or 62)\n		end\n	end)\n	applied.wrap = c\n	for _, m in ipairs(weaponModels()) do\n		paint(m, c, Enum.Material.SmoothPlastic)\n	end\n	return \"wrap applied locally\"\nend\n\nfunction SkinChanger.ApplyCharm(charmName: string): string\n	clearCharms()\n	applied.charm = charmName\n	if not charmName or #charmName == 0 or charmName == \"None\" then\n		return \"charm cleared\"\n	end\n	-- generic charm: small volt cube hanging off weapon (placeholder until real charm meshes dumped)\n	for _, m in ipairs(weaponModels()) do\n		local anchor: BasePart? = m:FindFirstChildWhichAffects(\"BasePart\", true) :: any\n		if not anchor then\n			for _, d in ipairs(m:GetDescendants()) do\n				if d:IsA(\"BasePart\") then\n					anchor = d\n					break\n				end\n			end\n		end\n		if anchor then\n			local p = Instance.new(\"Part\")\n			p.Name = \"LIV4Charm\"\n			p.Size = Vector3.new(0.25, 0.25, 0.25)\n			p.Color = Color3.fromRGB(198, 255, 62)\n			p.Material = Enum.Material.Neon\n			p.CanCollide = false\n			p.CanQuery = false\n			p.CanTouch = false\n			p.CFrame = (anchor :: BasePart).CFrame * CFrame.new(0, -0.6, 0)\n			p.Parent = m\n			local w = Instance.new(\"WeldConstraint\")\n			w.Part0 = anchor\n			w.Part1 = p\n			w.Parent = p\n		end\n	end\n	return \"charm applied locally: \" .. charmName\nend\n\nfunction SkinChanger.ApplyFinisher(finisherName: string): string\n	applied.finisher = finisherName\n	-- finishers are kill effects; locally we can only stage the effect hook.\n	-- Real mapping needs Dump() output; store choice so Effects can trigger it on kill.\n	return \"finisher staged locally: \" .. finisherName .. \" (plays on your kills only)\"\nend\n\nfunction SkinChanger.ClearAll(): string\n	applied = {}\n	clearCharms()\n	-- re-equip to restore original materials\n	local ch = myChar()\n	local eq = ch and ch:FindFirstChild(\"EquippedItem\")\n	if eq and (eq :: any).EquipItem then\n		-- no-op: leave to user to swap weapons to refresh\n	end\n	return \"cleared (swap weapons to refresh originals)\"\nend\n\n-- Dumps candidate skin/charm/finisher paths + equipped state. Run once, send back.\nfunction SkinChanger.Dump(): string\n	local lines = { \"=== LIV4 SkinChanger Dump ===\" }\n	table.insert(lines, \"models=\" .. tostring(#weaponModels()))\n	for _, m in ipairs(weaponModels()) do\n		table.insert(lines, \"model: \" .. m:GetFullName() .. \" children=\" .. tostring(#m:GetChildren()))\n		for _, d in ipairs(m:GetChildren()) do\n			if #lines > 60 then\n				break\n			end\n			table.insert(lines, \"  - \" .. d.ClassName .. \" \" .. d.Name)\n		end\n	end\n	local rs = game:GetService(\"ReplicatedStorage\")\n	for _, n in ipairs({ \"Modules\", \"Items\", \"Weapons\", \"Skins\", \"Cosmetics\" }) do\n		local f = rs:FindFirstChild(n)\n		table.insert(lines, n .. \": \" .. (f and f:GetFullName() or \"missing\"))\n	end\n	local ch = myChar()\n	local eq = ch and ch:FindFirstChild(\"EquippedItem\")\n	table.insert(lines, \"equipped: \" .. tostring(eq and eq.Name or \"none\"))\n	return table.concat(lines, \"\\n\")\nend\n\nfunction SkinChanger.Auto(Utils, Config)\n	for _, c in ipairs(conns) do\n		pcall(function()\n			c:Disconnect()\n		end)\n	end\n	table.clear(conns)\n	local S = Utils.Services\n	table.insert(conns, S.Players.LocalPlayer.CharacterAdded:Connect(function()\n		task.wait(1)\n		-- reapply wrap/skin after respawn\n		if applied.wrap then\n			for _, m in ipairs(weaponModels()) do\n				paint(m, applied.wrap, Enum.Material.SmoothPlastic)\n			end\n		end\n	end))\nend\n\nreturn SkinChanger\n\nlocal Config = loadMod(\"Config.luau\")\nlocal Utils = loadMod(\"Utils.luau\")\nlocal UILib = loadMod(\"UI.luau\")\nlocal AimMod = loadMod(\"Aimbot.luau\")\nlocal SilentMod = loadMod(\"SilentAim.luau\")\nlocal TrigMod = loadMod(\"Triggerbot.luau\")\nlocal ESPMod = loadMod(\"ESP.luau\")\nlocal MoveMod = loadMod(\"Movement.luau\")\nlocal FXMod = loadMod(\"Effects.luau\")\nlocal RageMod = loadMod(\"Ragebot.luau\")\nlocal SpoofMod = loadMod(\"Spoofer.luau\")\nlocal CMMod = loadMod(\"ConfigManager.luau\")\nlocal SkinMod = loadMod(\"SkinChanger.luau\")\nif not Config or not Utils then\n	error(\"[liv4] Config/Utils missing\")\nend\n\nlocal C = (getgenv() :: any).LIV4Config\nif AimMod then\n	AimMod.Start(Utils, Config)\nend\nif SilentMod then\n	SilentMod.Start(Utils, Config, function() return AimMod and AimMod.SilentTarget() end)\nend\nif TrigMod then\n	TrigMod.Start(Utils, Config, nil)\nend\nif ESPMod then\n	ESPMod.Start(Utils, Config)\nend\nif MoveMod then\n	MoveMod.Start(Utils, Config)\nend\nif FXMod then\n	FXMod.Start(Utils, Config)\nend\nif RageMod then\n	RageMod.Start(Utils, Config)\nend\nif CMMod then\n	CMMod.Ensure()\nend\nif SkinMod and SkinMod.Auto then\n	SkinMod.Auto(Utils, Config)\nend\n\nif UILib then\n	local win = UILib.New()\n\n	-- COMBAT (includes ragebot)\n	local combat = win:Tab(\"Combat\")\n	combat:Section(\"Aimbot\")\n	combat:Toggle(\"Enabled\", C.Combat.AimbotEnabled, function(v)\n		C.Combat.AimbotEnabled = v\n	end)\n	combat:Slider(\"FOV\", 30, 400, C.Combat.AimFOV, function(v)\n		C.Combat.AimFOV = math.round(v)\n	end)\n	combat:Slider(\"Smoothing\", 0.02, 1, C.Combat.AimSmoothing, function(v)\n		C.Combat.AimSmoothing = v\n	end)\n	combat:Dropdown(\"Hit Part\", { \"Head\", \"HitboxHead\", \"HumanoidRootPart\", \"Closest\" }, C.Combat.AimPart, function(v)\n		C.Combat.AimPart = v\n	end)\n	combat:Toggle(\"Target Dummies (range)\", C.Combat.TargetDummies ~= false, function(v)\n		C.Combat.TargetDummies = v\n	end)\n	combat:Slider(\"Prediction\", 0, 0.1, C.Combat.Prediction or 0.015, function(v)\n		C.Combat.Prediction = v\n	end)\n	combat:Toggle(\"Wall Check\", C.Combat.WallCheck == true, function(v)\n		C.Combat.WallCheck = v\n	end)\n	combat:Section(\"Silent Aim\")\n	combat:Toggle(\"Silent Enabled\", C.Combat.SilentEnabled, function(v)\n		C.Combat.SilentEnabled = v\n	end)\n	combat:Slider(\"Silent FOV\", 20, 300, C.Combat.SilentFOV, function(v)\n		C.Combat.SilentFOV = math.round(v)\n	end)\n	combat:Slider(\"Hit Chance\", 1, 100, C.Combat.SilentChance, function(v)\n		C.Combat.SilentChance = math.round(v)\n	end)\n	combat:Section(\"Triggerbot\")\n	combat:Toggle(\"Trigger Enabled\", C.Combat.TriggerEnabled, function(v)\n		C.Combat.TriggerEnabled = v\n	end)\n	combat:Slider(\"Reaction ms\", 0, 300, C.Combat.TriggerDelay, function(v)\n		C.Combat.TriggerDelay = math.round(v)\n	end)\n	combat:Section(\"Ragebot [risky]\")\n	combat:Toggle(\"Rage Enabled\", C.Combat.RageEnabled, function(v)\n		C.Combat.RageEnabled = v\n	end)\n	combat:Toggle(\"Void Spam\", C.Combat.RageVoidSpam, function(v)\n		C.Combat.RageVoidSpam = v\n	end)\n	combat:Textbox(\"Weapon\", \"Assault Rifle\", C.Combat.RageWeapon, function(v)\n		C.Combat.RageWeapon = v\n	end)\n	combat:Toggle(\"Anti-Aim\", C.Combat.RageAntiAim, function(v)\n		C.Combat.RageAntiAim = v\n	end)\n\n	-- VISUAL\n	local vis = win:Tab(\"Visual\")\n	vis:Section(\"ESP\")\n	vis:Toggle(\"Enabled\", C.Visual.ESPEnabled, function(v)\n		C.Visual.ESPEnabled = v\n	end)\n	vis:Toggle(\"Box\", C.Visual.Box, function(v)\n		C.Visual.Box = v\n	end)\n	vis:Toggle(\"Filled Box\", C.Visual.FilledBox, function(v)\n		if v then\n			C.Visual.FilledNoOutline = false\n		end\n		C.Visual.FilledBox = v\n	end)\n	vis:Toggle(\"Filled No Outline\", C.Visual.FilledNoOutline, function(v)\n		if v then\n			C.Visual.FilledBox = false\n		end\n		C.Visual.FilledNoOutline = v\n	end)\n	vis:Toggle(\"Skeleton\", C.Visual.Skeleton, function(v)\n		C.Visual.Skeleton = v\n	end)\n	vis:Toggle(\"Chams\", C.Visual.Chams, function(v)\n		C.Visual.Chams = v\n	end)\n	vis:Toggle(\"Name\", C.Visual.Name, function(v)\n		C.Visual.Name = v\n	end)\n	vis:Toggle(\"Distance\", C.Visual.Distance, function(v)\n		C.Visual.Distance = v\n	end)\n	vis:Toggle(\"Health Bar\", C.Visual.HealthBar, function(v)\n		C.Visual.HealthBar = v\n	end)\n	vis:Slider(\"HP Bar Thickness\", 2, 10, C.Visual.HealthBarThickness or 4, function(v)\n		C.Visual.HealthBarThickness = math.round(v)\n	end)\n	vis:Slider(\"Text Size\", 8, 24, C.Visual.TextSize, function(v)\n		C.Visual.TextSize = math.round(v)\n	end)\n\n	-- EXPLOITS\n	local ex = win:Tab(\"Exploits\")\n	ex:Section(\"Movement\")\n	ex:Toggle(\"Fly\", C.Exploits.Fly, function(v)\n		C.Exploits.Fly = v\n	end)\n	ex:Slider(\"Fly Speed\", 20, 200, C.Exploits.FlySpeed, function(v)\n		C.Exploits.FlySpeed = math.round(v)\n	end)\n	ex:Toggle(\"No Clip\", C.Exploits.Noclip, function(v)\n		C.Exploits.Noclip = v\n	end)\n	ex:Section(\"Avatar Spoofer (user id)\")\n	ex:Textbox(\"User Id\", \"123456\", C.Exploits.AvatarUserId, function(v)\n		C.Exploits.AvatarUserId = v\n	end)\n	ex:Button(\"Apply Outfit\", function()\n		if SpoofMod then\n			local m = SpoofMod.Avatar(C.Exploits.AvatarUserId)\n			game:GetService(\"StarterGui\"):SetCore(\"SendNotification\", { Title = \"liv4cheets\", Text = m, Duration = 3 })\n		end\n	end)\n	ex:Section(\"Game Spoofers (visual)\")\n	ex:Textbox(\"Level\", \"e.g. 100\", C.Exploits.LevelValue, function(v)\n		C.Exploits.LevelValue = v\n	end)\n	ex:Button(\"Spoof Level\", function()\n		if SpoofMod then\n			SpoofMod.Level(C.Exploits.LevelValue)\n		end\n	end)\n	ex:Textbox(\"Winstreak\", \"e.g. 50\", C.Exploits.StreakValue, function(v)\n		C.Exploits.StreakValue = v\n	end)\n	ex:Button(\"Spoof Winstreak\", function()\n		if SpoofMod then\n			SpoofMod.Streak(C.Exploits.StreakValue)\n		end\n	end)\n	ex:Textbox(\"Leaderboard Wins\", \"e.g. 999\", C.Exploits.BoardValue, function(v)\n		C.Exploits.BoardValue = v\n	end)\n	ex:Button(\"Spoof Leaderboard\", function()\n		if SpoofMod then\n			SpoofMod.Board(C.Exploits.BoardValue)\n		end\n	end)\n	ex:Textbox(\"Ranked Rating\", \"e.g. 3000\", C.Exploits.RankedValue, function(v)\n		C.Exploits.RankedValue = v\n	end)\n	ex:Button(\"Spoof Ranked\", function()\n		if SpoofMod then\n			SpoofMod.Ranked(C.Exploits.RankedValue)\n		end\n	end)\n	ex:Section(\"Animation Player (asset id)\")\n	ex:Textbox(\"Asset Id\", \"rbxassetid uid\", C.Exploits.AnimAssetId, function(v)\n		C.Exploits.AnimAssetId = v\n	end)\n	ex:Button(\"Play Animation\", function()\n		if SpoofMod then\n			SpoofMod.PlayAnim(C.Exploits.AnimAssetId)\n		end\n	end)\n	ex:Button(\"Stop Animation\", function()\n		if SpoofMod then\n			SpoofMod.StopAnim()\n		end\n	end)\n	ex:Section(\"Skin Changer (you-only)\")\n	ex:Textbox(\"Weapon\", \"Assault Rifle\", C.SkinChanger.Weapon, function(v)\n		C.SkinChanger.Weapon = v\n	end)\n	ex:Textbox(\"Skin\", \"e.g. Glacier\", C.SkinChanger.Skin, function(v)\n		C.SkinChanger.Skin = v\n	end)\n	ex:Textbox(\"Color Hex\", \"C6FF3E\", C.SkinChanger.ColorHex, function(v)\n		C.SkinChanger.ColorHex = v\n	end)\n	ex:Button(\"Apply Skin\", function()\n		if SkinMod then\n			SkinMod.ApplySkin(C.SkinChanger.Weapon, C.SkinChanger.Skin, C.SkinChanger.ColorHex)\n		end\n	end)\n	ex:Textbox(\"Wrap Hex\", \"C6FF3E\", C.SkinChanger.WrapHex, function(v)\n		C.SkinChanger.WrapHex = v\n	end)\n	ex:Button(\"Apply Wrap\", function()\n		if SkinMod then\n			SkinMod.ApplyWrap(C.SkinChanger.WrapHex)\n		end\n	end)\n	ex:Dropdown(\"Charm\", { \"None\", \"Volt Cube\", \"Star\", \"Skull\" }, C.SkinChanger.Charm, function(v)\n		C.SkinChanger.Charm = v\n		if SkinMod then\n			SkinMod.ApplyCharm(v)\n		end\n	end)\n	ex:Dropdown(\"Finisher\", { \"None\", \"Volt Burst\", \"Ghost\", \"Fire\" }, C.SkinChanger.Finisher, function(v)\n		C.SkinChanger.Finisher = v\n		if SkinMod then\n			SkinMod.ApplyFinisher(v)\n		end\n	end)\n	ex:Button(\"Clear Skins\", function()\n		if SkinMod then\n			SkinMod.ClearAll()\n		end\n	end)\n	ex:Button(\"Dump Skin Paths\", function()\n		if SkinMod then\n			local s = SkinMod.Dump()\n			print(s)\n			if setclipboard then\n				pcall(setclipboard, s)\n			end\n		end\n	end)\n\n	-- CONFIGS\n	local cf = win:Tab(\"Configs\")\n	cf:Section(\"Local JSON configs\")\n	cf:Textbox(\"Config Name\", \"myconfig\", \"\", function(v)\n		(getgenv() :: any).LIV4ConfigName = v\n	end)\n	cf:Button(\"Save\", function()\n		if CMMod then\n			CMMod.Save((getgenv() :: any).LIV4ConfigName or \"default\")\n		end\n	end)\n	cf:Button(\"Load\", function()\n		if CMMod then\n			CMMod.Load((getgenv() :: any).LIV4ConfigName or \"default\")\n		end\n	end)\n	cf:Button(\"Delete\", function()\n		if CMMod then\n			CMMod.Delete((getgenv() :: any).LIV4ConfigName or \"default\")\n		end\n	end)\n\n	-- MISC\n	local mi = win:Tab(\"Misc\")\n	mi:Section(\"Theme\")\n	mi:Dropdown(\"Theme\", { \"Default\", \"Onyx\" }, C.Misc.Theme, function(v)\n		C.Misc.Theme = v\n		win:ApplyTheme(v)\n	end)\n	mi:Section(\"Fonts\")\n	mi:Dropdown(\"Menu Font\", { \"GothamMedium\", \"Gotham\", \"GothamBold\", \"GothamBlack\", \"Code\", \"Montserrat\", \"Arial\" }, C.Misc.MenuFont, function(v)\n		C.Misc.MenuFont = v\n		win:SetMenuFont(v)\n	end)\n	mi:Slider(\"In-Game Text Size\", 8, 24, C.Visual.TextSize, function(v)\n		C.Visual.TextSize = math.round(v)\n		C.Misc.GameFontSize = math.round(v)\n	end)\n	mi:Section(\"Behavior\")\n	mi:Toggle(\"Hover / Animations\", C.Misc.Anims, function(v)\n		C.Misc.Anims = v\n	end)\n	mi:Textbox(\"Watermark\", \"liv4cheets\", C.Misc.Watermark, function(v)\n		C.Misc.Watermark = v\n	end)\n	mi:Button(\"Unload\", function()\n		local esp = (getgenv() :: any).LIV4ESP\n		if esp and esp.Destroy then\n			pcall(function()\n				esp.Destroy()\n			end)\n		end\n		local g = (getgenv() :: any).LIV4UI\n		if g then\n			pcall(function()\n				g:Destroy()\n			end)\n		end\n	end)\n	win:ApplyTheme(C.Misc.Theme)\n	win:SetMenuFont(C.Misc.MenuFont)\nend\n\nprint(\"[liv4] loaded\")\n\nprint(\"[liv4] loaded\")\n")()